        const disc = R() < .25 ? pick([0.05, 0.1, 0.15, 0.2]) : 0;
        const qty = p[3] < 500 ? int(1, 3) : 1;
        const priceAtSale = d.getUTCFullYear() === 2023 ? Math.round(p[3] * 0.9) : p[3];
        items.push([iid++, oid, p[0], qty, priceAtSale, disc]);
