  const ParaBirimleri = [{ ParaBirimi: 'TRY', Sembol: '₺', Sira: 1 }, { ParaBirimi: 'USD', Sembol: '$', Sira: 2 }, { ParaBirimi: 'EUR', Sembol: '€', Sira: 3 }];
