    if (o.pct) { const tot = acc.slice(); cum.forEach(c => { c[0] = c[0].map((v, i) => tot[i] ? v / tot[i] : 0); c[1] = c[1].map((v, i) => tot[i] ? v / tot[i] : 0); }); }
