/* ═══════════════════════ 4) MÜŞTERİ KÂRLILIĞI ═══════════════════════ */
const KX = { 'Aktif Ay': 'COUNTROWS(FILTER(VALUES(Tarih[YilAy]), [Sipariş Sayısı] > 0))', 'Aylık Değer': 'DIVIDE([Net Satış], [Aktif Ay])', 'Müşteri Başı Brüt Kâr': 'DIVIDE([Brüt Kâr], [Müşteri Sayısı])', 'Brüt Kâr GY': 'CALCULATE([Brüt Kâr], SAMEPERIODLASTYEAR(Tarih[Tarih]))', 'Kâr Marjı GY': 'CALCULATE([Kâr Marjı %], SAMEPERIODLASTYEAR(Tarih[Tarih]))' };
const KF = { 'Brüt Kâr': 'para', 'Net Satış': 'para' };
function custQ(a, o) {
  return memo(skey(a, 'cq', o), () => { const r = a.Q(['Musteriler[MusteriNo]'], ['Net Satış', 'Brüt Kâr', 'Kâr Marjı %', 'Sipariş Sayısı', 'Aktif Ay', 'Ortalama İndirim %'], Object.assign({ extraMeasures: KX, totals: false }, o || {}));
    return r.rows.filter(x => x.vals[0] > 0).map(x => ({ no: x.keys[0], ns: x.vals[0], bk: x.vals[1] || 0, m: x.vals[2], ord: x.vals[3] || 0, am: x.vals[4] || 0, ind: x.vals[5] || 0, c: CUST[x.keys[0]] || {} })); });
}
const quad = rows => { const mx = rows.length ? sum(rows.map(r => r.ns)) / rows.length : 0, my = rows.length ? sum(rows.map(r => r.m)) / rows.length : 0; const q = r => r.ns >= mx ? (r.m >= my ? 'Yıldız' : 'Hacim') : (r.m >= my ? 'Niş' : 'Gözden geçir'); return { mx, my, q }; };
const ktip = (a, add, cat) => {
  const o = { add, extraMeasures: KX }; const top = sortBy(a.Q(['Musteriler[MusteriNo]'], ['Brüt Kâr'], { add, totals: false }), 0).rows.slice(0, 5); const r = a.Q([a.timeAxis], ['Kâr Marjı %'], { add, totals: false });
  return { title: 'Araç ipucu · ' + cat, cards: [['Müşteri', a.fmt(a.M('[Müşteri Sayısı]', o), 'adet')], ['Müşteri başı brüt kâr', a.fmt(a.M('[Müşteri Başı Brüt Kâr]', o), 'para', true)], ['Kâr marjı', a.fmt(a.M('[Kâr Marjı %]', o), 'yuzde')], ['Ort. indirim', a.fmt(a.M('[Ortalama İndirim %]', o), 'yuzde')]], bars: top.map(x => [cname(x.keys[0]), x.vals[0], a.fmt(x.vals[0], 'para', true)]), barsLabel: 'En kârlı 5 müşteri', spark: col(r, 0), sparkLabel: 'Aylık marj' };
};
const knav = (n, sp) => nav('knav' + n, [{ label: 'Kârlılık haritası', icon: '◈', page: 'genel' }, { label: 'Değer ve Pareto', icon: '▟', page: 'deger' }, { label: 'Etkileyenler', icon: '⚲', page: 'etken' }], sp || 8);
const KDEF = (() => { const t = {}; T.Satislar.rows.forEach(r => { if (r.Durum !== 'İptal') t[r.MusteriNo] = (t[r.MusteriNo] || 0) + r.Tutar - r.Maliyet; }); return +Object.keys(t).sort((x, y) => t[y] - t[x])[0]; })();

