const mhNav = id => navTile(id, [{ label: 'Grafik', icon: '▲', vis: 'gorunum:grafik' }, { label: 'Tablo', icon: '▦', vis: 'gorunum:tablo' }, { label: 'Yüksek öncelik', icon: '!', bm: 'yuksek' }, { label: 'E-posta kanalı', icon: '@', bm: 'eposta' }], 'Görünüm ve yer işaretleri');

