/* --- Value, Type, Error, Function --- */
LIB.set('Value.Is', new MFunc(a => { const v = force(a[0]), t = force(a[1]); if (!(t instanceof MType)) throw convErr(t, 'Type'); return isType(v, t); }, 'Value.Is', 2, 2));
