const proper = s => trLo(s).replace(/(^|[\s\-'’(])(\S)/g, (m, a, b) => a + trUp(b));

/* ---------- Tablo yardımcıları ---------- */
const clone = t => ({ cols: t.cols.map(c => Object.assign({}, c)), rows: t.rows.map(r => r.slice()) });
