const LESSONS = (window.PBI_LESSONS || []).map((l, i) => ({ l, i })).sort((a, b) => { const ia = ORDER.indexOf(a.l.id), ib = ORDER.indexOf(b.l.id); return (ia < 0 ? 900 + a.i : ia) - (ib < 0 ? 900 + b.i : ib); }).map(x => x.l);
