function measureSet(excludeName) {
  const ms = {};
  LIB.forEach(m => { if (m.name !== excludeName) ms[m.name] = { name: m.name, expr: m.expr }; });
  (P.mine || []).forEach(m => { if (m.name !== excludeName && m.name) ms[m.name] = { name: m.name, expr: m.expr }; });
  return ms;
}
