  h += '<div class="labgrid"><nav class="panel lablist" aria-label="Kalıplar"><select id="labSel" class="input" aria-label="Kalıp seç">' + LV.map(L => '<optgroup label="' + L.name + '">' + PATS.filter(x => x.lv === L.id).map(x => '<option value="' + x.id + '"' + (x.id === p.id ? ' selected' : '') + '>' + esc(x.name) + ' (' + nLines(x) + ' satır)</option>').join('') + '</optgroup>').join('') + '</select>' + LV.map(L => '<div class="llg"><span class="eyebrow">' + L.name + '</span>' + PATS.filter(x => x.lv === L.id).map(x => '<button data-lab="' + x.id + '" aria-current="' + (x.id === p.id) + '"><span>' + esc(x.name) + '</span><small>' + nLines(x) + '</small>' + (C.P.labSeen[x.id] ? '<i class="seen" title="İncelendi">✓</i>' : '') + '</button>').join('') + '</div>').join('') + '</nav>';
